/*
 * A343727  Numbers with all digits odd whose squares have only one odd digit.
 * https://oeis.org/A343727
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 6, u16 n <= 15, u32 n <= 39, u64 n <= 46, u128 n <= 46,
 *            big any n
 * Helpers:   append_candidate, digit_frequencies
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A343727: Generated by exhaustive search over all decimal numbers whose digits
 * are all odd; a number is accepted if its square contains exactly one odd digit
 * (necessarily the last).  The numbers are produced in increasing order and
 * cached so that any call to a(idx_t n) returns the correct nth term. */

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include "../utils/append_candidate.h"
#include "../utils/digit_frequencies.h"

static const uint8_t odd_digits[5] = {1, 3, 5, 7, 9};

static seq_t *g_cache = NULL;          /* cache of found terms */
static size_t g_cache_len = 0;          /* number of cached terms */
static size_t g_cache_cap = 0;          /* capacity of cache */
static idx_t  g_processed_len = 0;      /* last length that has been processed */

/* Recursive generator that builds all numbers of a given length consisting
 * of odd digits and tests whether the number meets the sequence condition.
 * The recursion walks numbers in lexicographic (hence numeric) order. */
static void generate_len_rec(idx_t len, idx_t pos, seq_t current)
{
    if (pos == len) {
        seq_t sq = current * current;
        unsigned int freq[10] = {0};
        digit_frequencies(sq, freq);
        unsigned int oddcnt = freq[1] + freq[3] + freq[5] + freq[7] + freq[9];
        if (oddcnt == 1) {
            append_candidate(&g_cache, &g_cache_len, &g_cache_cap, current);
        }
        return;
    }
    for (int i = 0; i < 5; ++i) {
        seq_t next = current * 10 + odd_digits[i];
        generate_len_rec(len, pos + 1, next);
    }
}

/* Public function required by the build system.  It guarantees that at least
 * n terms of A343727 are computed and cached, then returns the nth term. */
seq_t a(idx_t n)
{
    if (n == 0) return 0ULL;   /* undefined for 0, return 0 as a safe fallback */

    /* Generate new lengths until we have at least n terms cached. */
    while (g_cache_len < n) {
        ++g_processed_len;
        generate_len_rec(g_processed_len, 0, 0);
    }

    return g_cache[n - 1];
}
